
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_rppscan_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_rppscan", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.884521777334244e+00, -4.785632144741239e+00, -4.647022175645676e+00, -4.454924099379118e+00, -4.192975444820322e+00, -3.843929651194251e+00, -3.393778402520468e+00, -2.839187242470251e+00, -2.197295713953036e+00, -1.505225951636650e+00, -8.555786058514178e-01, -6.231261246320634e-01, -6.329149473324147e-01, -5.322443837214890e-01, -3.631447524079080e-01, -1.982902304621531e-01, -7.907183432436324e-02, -2.116755797060682e-02, -2.966789394582804e-03, -1.387599574091252e-04]))
    err = ns.abs(tgt-ref_tgt)/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    tol = ns.full_like(tgt, ns.asarray([5.000000000000000e-08, 5.000000000000000e-08, 5.000000000000000e-08, 5.000000000000000e-08, 5.000000000000000e-08, 5.000000000000000e-08, 5.000000000000000e-08, 5.000000000000000e-08, 5.000000000000000e-08, 5.000000000000000e-08, 5.000000000000000e-08, 5.000000000000000e-08, 5.000000000000000e-08, 5.000000000000000e-08, 5.000000000000000e-08, 5.000000000000000e-08, 5.000000000000000e-08, 5.000000000000000e-08, 5.000000000000000e-08, 5.000000000000000e-07]))
    assert bool(ns.all(err < tol))


